// ── RegOS Escalation: Validate & Enrich ──
// n8n v2 webhook wraps POST body — handle both nested and flat.

const raw = $input.first().json;
const item = raw.body && typeof raw.body === 'object' && raw.body.case_ref
  ? raw.body
  : raw;

// Validate required fields
const required = ['case_ref', 'timestamp', 'user', 'query', 'confidence', 'escalation'];
const missing = required.filter(f => !item[f]);

if (missing.length > 0) {
  const receivedKeys = Object.keys(item).join(', ');
  throw new Error(`Missing required fields: ${missing.join(', ')}. Received keys: ${receivedKeys}`);
}

// Enrich with processing metadata
const enriched = {
  ...item,
  pipeline: {
    received_at: new Date().toISOString(),
    workflow_version: '1.1.0',
    status: 'received',
    reviewer_assigned: null,
    resolution: null
  }
};

return [{ json: enriched }];

// ── RegOS Escalation: Generate Raw Case File ──
// Stores the FULL context dump as a downloadable JSON file.
// Reviewers can download this from n8n Execution History.

const item = $input.first().json;

// Build the complete raw case file with all context
const caseFile = {
  _meta: {
    title: `Escalation Case ${item.case_ref}`,
    generated: new Date().toISOString(),
    pipeline_version: item.pipeline?.workflow_version || '1.1.0',
    type: 'raw_dump'
  },
  case_ref: item.case_ref,
  status: 'pending_review',
  timestamp: item.timestamp,
  user: item.user || {},
  query: item.query,
  response: item.response || '',
  confidence: {
    score: item.confidence?.score,
    band: item.confidence?.band,
    score_percent: item.confidence?.score ? Math.round(item.confidence.score * 100) + '%' : 'N/A',
    signals: item.confidence?.signals || {}
  },
  escalation_reason: item.escalation?.reason || 'Unknown',
  conversation_history: item.conversation_history || [],
  retrieval_context: item.retrieval_context || {},
  context: item.context || {}
};

const jsonString = JSON.stringify(caseFile, null, 2);
const buffer = Buffer.from(jsonString, 'utf-8');

return [{
  json: { ...item, raw_case_file: caseFile },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: `${item.case_ref}_raw.json`,
      fileExtension: 'json'
    }
  }
}];

