// ── RegOS Escalation: Format Email v2 ──
// Renders a professional HTML email from the case packet.
// Properly converts markdown to HTML, humanizes field names,
// and handles missing data gracefully.

const item = $input.first().json;

const caseRef = item.case_ref || 'UNKNOWN';
const trigger = (item.escalation?.trigger === 'manual') ? 'MANUAL' : 'AUTO';

// ── Confidence display ──
const score = item.confidence?.score;
const band = item.confidence?.band;
let confidenceDisplay = '';
if (score != null && score > 0) {
  const pct = Math.round(score * 100);
  const bandLabel = band && band !== 'N/A' ? ` · ${band}` : '';
  confidenceDisplay = `${pct}%${bandLabel}`;
} else {
  confidenceDisplay = 'Not available (non-RegOS response)';
}

// ── User info ──
const userName = item.user?.name || 'Unknown';
const userEmail = item.user?.email || '';
const userRole = item.user?.role || '';

// ── Humanize reason ──
const reasonMap = {
  'manual_user_flag': 'Manually flagged by user',
  'low_confidence': 'Low confidence score',
  'threshold_breach': 'Confidence below threshold',
  'guardrail_triggered': 'Guardrail triggered',
};
const rawReason = item.escalation?.reason || 'Unknown';
const reason = reasonMap[rawReason] || rawReason.replace(/_/g, ' ');

const query = item.query || '(no query captured)';
const response = item.response || '(no response captured)';
const chatId = item.context?.chat_id || '';
const timestamp = item.timestamp || new Date().toISOString();

// ── Markdown → HTML converter ──
function md2html(text) {
  if (!text) return '';
  return text
    // Escape HTML entities first
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    // Headers
    .replace(/^### (.+)$/gm, '<h4 style="color:#1B3A5C;margin:14px 0 6px;font-size:13px">$1</h4>')
    .replace(/^## (.+)$/gm, '<h3 style="color:#1B3A5C;margin:16px 0 8px;font-size:14px">$1</h3>')
    .replace(/^# (.+)$/gm, '<h2 style="color:#1B3A5C;margin:18px 0 8px;font-size:16px">$1</h2>')
    // Bold + italic
    .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
    // Bold
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    // Italic
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    // Inline code
    .replace(/`([^`]+)`/g, '<code style="background:#f0f0f0;padding:1px 5px;border-radius:3px;font-size:12px">$1</code>')
    // Blockquotes
    .replace(/^&gt; (.+)$/gm, '<div style="border-left:3px solid #ccc;padding:4px 12px;margin:6px 0;color:#555">$1</div>')
    // Unordered lists
    .replace(/^[-*] (.+)$/gm, '<div style="padding:2px 0 2px 16px">• $1</div>')
    // Numbered lists
    .replace(/^\d+\. (.+)$/gm, '<div style="padding:2px 0 2px 16px">$1</div>')
    // Citations [G1], [G2] etc
    .replace(/\[(G\d+)\]/g, '<span style="background:#E8F4FD;color:#1B3A5C;padding:1px 4px;border-radius:2px;font-size:11px;font-weight:600">$1</span>')
    // Section references (Sec. 24-xxx)
    .replace(/(Sec(?:tion)?\.?\s*24[-–]\d+(?:\.\d+)*(?:\([^)]+\))?)/g, '<span style="background:#FFF3E0;padding:1px 4px;border-radius:2px;font-size:12px">$1</span>')
    // Line breaks
    .replace(/\n\n/g, '</p><p style="margin:8px 0">')
    .replace(/\n/g, '<br>');
}

// ── Format the AI response ──
const responseHtml = md2html(response);
const responseTruncated = response.length > 3000;
const responseDisplay = responseTruncated
  ? md2html(response.substring(0, 3000)) + '<br><em style="color:#888">… truncated — see attached case file for full response</em>'
  : responseHtml;

// ── User's concern (from the popup input) ──
const userConcern = item.escalation?.user_concern || '';
let concernHtml = '';
let concernText = '';
if (userConcern.trim()) {
  concernText = userConcern;
  concernHtml = md2html(userConcern);
}

// ── Retrieval context summary ──
const citations = item.retrieval_context?.graphrag_citations || [];
const kbSources = item.retrieval_context?.kb_sources || [];
const entities = item.retrieval_context?.entity_matches || [];
const hasContext = citations.length > 0 || kbSources.length > 0 || entities.length > 0;

let contextHtml = '';
if (hasContext) {
  if (citations.length > 0) {
    contextHtml += `<div style="margin-bottom:12px"><strong style="color:#1B3A5C">Graph Citations (${citations.length})</strong>`;
    citations.forEach((c, i) => {
      const section = c.section || c.id || `Citation ${i+1}`;
      const snippet = (c.content || '').substring(0, 200);
      contextHtml += `<div style="background:#f8f9fa;padding:8px 12px;margin:4px 0;border-radius:4px;font-size:12px"><span style="background:#E8F4FD;color:#1B3A5C;padding:1px 4px;border-radius:2px;font-size:11px;font-weight:600">G${c.index || i+1}</span> <strong>${section}</strong>${snippet ? '<br><span style="color:#666">' + snippet + '…</span>' : ''}</div>`;
    });
    contextHtml += '</div>';
  }
  if (kbSources.length > 0) {
    contextHtml += `<div style="margin-bottom:12px"><strong style="color:#1B3A5C">Knowledge Base Sources (${kbSources.length})</strong>`;
    kbSources.forEach(s => {
      contextHtml += `<div style="background:#f8f9fa;padding:6px 12px;margin:4px 0;border-radius:4px;font-size:12px">${s.name || 'Unnamed source'}</div>`;
    });
    contextHtml += '</div>';
  }
  if (entities.length > 0) {
    contextHtml += `<div><strong style="color:#1B3A5C">Entity Matches (${entities.length})</strong>`;
    contextHtml += '<div style="margin:4px 0;font-size:12px">' + entities.map(e => `<span style="background:#EDE7F6;padding:2px 8px;border-radius:12px;margin:2px 4px 2px 0;display:inline-block">${e.name || e}</span>`).join('') + '</div></div>';
  }
}

// ── Confidence bar visual ──
let confidenceBar = '';
if (score != null && score > 0) {
  const pct = Math.round(score * 100);
  const barColor = pct >= 85 ? '#27AE60' : pct >= 60 ? '#F39C12' : '#E74C3C';
  confidenceBar = `
    <div style="margin:4px 0">
      <div style="background:#eee;border-radius:4px;height:8px;width:200px;display:inline-block;vertical-align:middle">
        <div style="background:${barColor};border-radius:4px;height:8px;width:${pct * 2}px"></div>
      </div>
      <span style="font-weight:600;color:${barColor};margin-left:8px">${pct}%</span>
      <span style="color:#888;font-size:12px;margin-left:4px">${band || ''}</span>
    </div>`;
}

// ── Subject line ──
const subject = `[RegOS Escalation] ${caseRef} — ${trigger === 'MANUAL' ? 'Manual Flag' : 'Auto-Escalated'}`;

// ── Trigger badge colors ──
const triggerBg = trigger === 'MANUAL' ? '#D4820A' : '#C0392B';
const triggerLabel = trigger === 'MANUAL' ? 'MANUAL FLAG' : 'AUTO-ESCALATED';

// ── Date formatting ──
const dateObj = new Date(timestamp);
const dateStr = dateObj.toLocaleString('en-US', {
  weekday: 'short', year: 'numeric', month: 'short', day: 'numeric',
  hour: '2-digit', minute: '2-digit', timeZoneName: 'short'
});

// ── HTML Email Body ──
const htmlBody = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#333;background:#f5f5f5;margin:0;padding:20px">
<div style="max-width:680px;margin:0 auto">

  <!-- Header -->
  <div style="background:linear-gradient(135deg,#1B3A5C,#2C5F8A);color:#fff;padding:24px 28px;border-radius:8px 8px 0 0">
    <table style="width:100%"><tr>
      <td><h1 style="margin:0;font-size:22px;font-weight:600">RegOS Escalation</h1>
        <p style="margin:6px 0 0;font-size:13px;color:#A8C8E8">${dateStr}</p></td>
      <td style="text-align:right;vertical-align:top">
        <span style="background:${triggerBg};color:#fff;padding:4px 12px;border-radius:4px;font-size:11px;font-weight:700;letter-spacing:0.5px">${triggerLabel}</span>
      </td>
    </tr></table>
  </div>

  <!-- Body -->
  <div style="background:#fff;border:1px solid #e0e0e0;border-top:none;padding:24px 28px;border-radius:0 0 8px 8px">

    <!-- Case info grid -->
    <table style="width:100%;border-collapse:collapse;margin-bottom:20px">
      <tr>
        <td style="padding:10px 16px;background:#f8f9fb;border:1px solid #eee;width:50%">
          <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:0.5px">Case Reference</div>
          <div style="font-size:15px;font-weight:600;color:#1B3A5C;margin-top:2px;font-family:monospace">${caseRef}</div>
        </td>
        <td style="padding:10px 16px;background:#f8f9fb;border:1px solid #eee;width:50%">
          <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:0.5px">Reason</div>
          <div style="font-size:14px;font-weight:500;margin-top:2px">${reason}</div>
        </td>
      </tr>
      <tr>
        <td style="padding:10px 16px;background:#f8f9fb;border:1px solid #eee">
          <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:0.5px">Flagged By</div>
          <div style="font-size:14px;margin-top:2px">${userName}${userEmail ? ' <span style="color:#888">&lt;' + userEmail + '&gt;</span>' : ''}${userRole ? ' <span style="background:#E8F0FE;color:#1B3A5C;padding:1px 6px;border-radius:3px;font-size:11px;margin-left:4px">' + userRole + '</span>' : ''}</div>
        </td>
        <td style="padding:10px 16px;background:#f8f9fb;border:1px solid #eee">
          <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:0.5px">Confidence</div>
          ${confidenceBar || `<div style="font-size:14px;margin-top:2px;color:#888">${confidenceDisplay}</div>`}
        </td>
      </tr>
    </table>

    <!-- User Query -->
    <div style="margin-bottom:20px">
      <h2 style="color:#1B3A5C;font-size:14px;margin:0 0 8px;padding-bottom:6px;border-bottom:2px solid #1DA1D4">User Query</h2>
      <div style="background:#F7FAFC;padding:14px 16px;border-left:4px solid #1DA1D4;border-radius:0 4px 4px 0;font-size:14px;line-height:1.5">${md2html(query)}</div>
    </div>

    <!-- AI Response -->
    <div style="margin-bottom:20px">
      <h2 style="color:#1B3A5C;font-size:14px;margin:0 0 8px;padding-bottom:6px;border-bottom:2px solid #E67E22">AI Response <span style="font-weight:400;color:#E67E22;font-size:12px">— Under Review</span></h2>
      <div style="background:#FFFBF5;padding:14px 16px;border-left:4px solid #E67E22;border-radius:0 4px 4px 0;font-size:13px;line-height:1.6"><p style="margin:0">${responseDisplay}</p></div>
    </div>

    ${hasContext ? `
    <!-- Retrieval Context -->
    <div style="margin-bottom:20px">
      <h2 style="color:#1B3A5C;font-size:14px;margin:0 0 8px;padding-bottom:6px;border-bottom:2px solid #8E44AD">Retrieval Context</h2>
      <div style="padding:4px 0">${contextHtml}</div>
    </div>
    ` : ''}

    ${concernHtml ? `
    <!-- User's Concern -->
    <div style="margin-bottom:20px">
      <h2 style="color:#1B3A5C;font-size:14px;margin:0 0 8px;padding-bottom:6px;border-bottom:2px solid #E74C3C">Reviewer Note <span style="font-weight:400;color:#E74C3C;font-size:12px">— from ${userName}</span></h2>
      <div style="background:#FDF2F2;padding:14px 16px;border-left:4px solid #E74C3C;border-radius:0 4px 4px 0;font-size:14px;line-height:1.6"><p style="margin:0">${concernHtml}</p></div>
    </div>
    ` : ''}

    ${chatId ? `
    <!-- Metadata footer -->
    <div style="background:#f8f9fb;padding:10px 14px;border-radius:4px;font-size:11px;color:#888;margin-top:16px">
      <strong>Chat ID:</strong> <span style="font-family:monospace">${chatId}</span>
    </div>
    ` : ''}

    <!-- Footer -->
    <div style="margin-top:24px;padding-top:16px;border-top:1px solid #eee;font-size:11px;color:#aaa;line-height:1.5">
      RegOS Escalation Pipeline v1.1.0 · Raw case file attached as JSON<br>
      Do not reply to this email — replies go to noreply@regos.ai
    </div>

  </div>
</div>
</body></html>`;

// ── Plain-text fallback ──
const divider = '─'.repeat(50);
const textBody = [
  `REGOS ESCALATION — ${caseRef}`,
  divider,
  '',
  `Trigger:     ${triggerLabel}`,
  `Reason:      ${reason}`,
  `Confidence:  ${confidenceDisplay}`,
  `Flagged by:  ${userName}${userEmail ? ' <' + userEmail + '>' : ''}${userRole ? ' (' + userRole + ')' : ''}`,
  `Date:        ${dateStr}`,
  chatId ? `Chat ID:     ${chatId}` : '',
  '',
  divider,
  'USER QUERY',
  divider,
  query,
  '',
  divider,
  'AI RESPONSE (UNDER REVIEW)',
  divider,
  response.substring(0, 3000),
  responseTruncated ? '\n… truncated — see attached case file' : '',
  '',
  concernText ? [divider, `REVIEWER NOTE (from ${userName})`, divider, concernText].join('\n') : '',
  '',
  divider,
  'Raw case file attached as JSON.',
  'RegOS Escalation Pipeline v1.1.0',
].filter(l => l !== null).join('\n');

return [{
  json: {
    ...item,
    email_subject: subject,
    email_html: htmlBody,
    email_text: textBody
  },
  binary: $input.first().binary
}];
